

# This file was *autogenerated* from the file /workspace/leanproject/Submission/check_both_roots.sage
from sage.all_cmdline import *   # import sage library

_sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_36 = Integer(36); _sage_const_4 = Integer(4); _sage_const_3 = Integer(3); _sage_const_1000 = Integer(1000); _sage_const_1en100 = RealNumber('1e-100')
def choose(n, k):
    if k < _sage_const_0  or k > n: return _sage_const_0 
    return binomial(n, k)

def a(n):
    if n == _sage_const_0 : return _sage_const_1 
    r = n - _sage_const_1 
    s = _sage_const_0 
    for k in range(n + _sage_const_1 ):
        s += choose(n, k) * choose(_sage_const_2 *n + k - _sage_const_1 , r)
    return s

for m in range(_sage_const_1 , _sage_const_36 ):
    print(f"\n--- Checking m = {m} ---")
    n_vars = _sage_const_4  * m + _sage_const_1 
    
    b = [QQ(a(m*i)) for i in range(_sage_const_3 *m + _sage_const_3 )]
    
    varnames = [f'c{i}' for i in range(_sage_const_2 *m+_sage_const_1 )] + [f'd{i}' for i in range(_sage_const_2 *m)]
    ring = PolynomialRing(QQ, names=varnames)
    vars = list(ring.gens())
    
    eqs = []
    for n in range(_sage_const_1 , _sage_const_3 *m + _sage_const_2 ):
        plus = prod(_sage_const_2 *m*n + k for k in range(_sage_const_1 , _sage_const_2 *m + _sage_const_1 ))
        minus = prod(_sage_const_2 *m*n - k for k in range(_sage_const_1 , _sage_const_2 *m + _sage_const_1 ))
        
        P_pos = sum(vars[i] * n**i for i in range(_sage_const_2 *m + _sage_const_1 ))
        P_neg = sum(vars[i] * (-n)**i for i in range(_sage_const_2 *m + _sage_const_1 ))
        
        sign_m = (-_sage_const_1 )**m
        Q_val = sum(vars[_sage_const_2 *m + _sage_const_1  + i] * (n**_sage_const_2 )**i for i in range(_sage_const_2 *m)) + (n**_sage_const_2 )**(_sage_const_2 *m)
        
        eq = plus * P_pos * b[n+_sage_const_1 ] + sign_m * minus * P_neg * b[n-_sage_const_1 ] - Q_val * b[n]
        eqs.append(eq)
        
    for k in range(_sage_const_1 , m + _sage_const_1 ):
        eq = sum(vars[i] * k**i for i in range(_sage_const_2 *m + _sage_const_1 )) - sum(vars[i] * (_sage_const_1  - k)**i for i in range(_sage_const_2 *m + _sage_const_1 ))
        eqs.append(eq)
        
    A = matrix(QQ, n_vars, n_vars)
    B = vector(QQ, n_vars)
    
    for r_idx, eq in enumerate(eqs):
        for c_idx, v in enumerate(vars):
            A[r_idx, c_idx] = eq.coefficient(v)
        B[r_idx] = -eq.subs({v: _sage_const_0  for v in vars})
        
    sol = A.solve_right(B)
    c_sol = [sol[i] for i in range(_sage_const_2 *m + _sage_const_1 )]
    d_sol = [sol[_sage_const_2 *m + _sage_const_1  + i] for i in range(_sage_const_2 *m)] + [_sage_const_1 ]
    
    R_x = QQ['x']
    P_poly = sum(c_sol[i] * R_x.gen()**i for i in range(_sage_const_2 *m + _sage_const_1 ))
    
    R_y = QQ['y']
    Q_poly = sum(d_sol[i] * R_y.gen()**i for i in range(_sage_const_2 *m + _sage_const_1 ))
    
    roots_P = P_poly.roots(ring=ComplexField(_sage_const_1000 ))
    roots_Q = Q_poly.roots(ring=ComplexField(_sage_const_1000 ))
    
    P_ok = True
    for r, mult in roots_P:
        is_real = abs(r.imag()) < _sage_const_1en100 
        in_01 = r.real() >= _sage_const_0  and r.real() <= _sage_const_1 
        if not is_real or not in_01:
            P_ok = False
            print(f"  P root violation for m = {m}: root = {r}")
            break
            
    Q_ok = True
    for r, mult in roots_Q:
        is_real = abs(r.imag()) < _sage_const_1en100 
        in_01 = r.real() >= _sage_const_0  and r.real() <= _sage_const_1 
        if not is_real or not in_01:
            Q_ok = False
            print(f"  Q root violation for m = {m}: root = {r}")
            break
            
    print(f"  m = {m}: P ok = {P_ok}, Q ok = {Q_ok}")

